extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var validator = await instantiate_script("res://story/story_validator.gd")
	if not check("istanza", validator != null, "Lo script story_validator.gd deve potersi istanziare senza errori"):
		return
	if not check("ha_metodi", has_function(validator, "validate_chapter") and has_function(validator, "validate_lines") and has_function(validator, "find_unreachable_labels"), "StoryValidator deve implementare validate_chapter, validate_lines e find_unreachable_labels"):
		return

	var valid_branching: Array = call_if_exists(validator, "validate_chapter", ["res://story/branching_story.json"], ["errore"])
	check("branching_valido", valid_branching.is_empty(), "I file corretti del gioco (es. branching_story.json) non devono generare errori (trovati: %d)" % valid_branching.size())

	var bad_speaker: Array = call_if_exists(validator, "validate_lines", [[
		{"type": "line", "speaker": "OmbraMisteriosa", "text": "Chi va la'?"}
	], "test.json"], [])
	check("trova_speaker", not bad_speaker.is_empty(), "Un personaggio non in KNOWN_SPEAKERS deve essere segnalato come errore")

	var bad_jump: Array = call_if_exists(validator, "validate_lines", [[
		{"type": "jump", "target": "porta_inesistente"}
	], "test.json"], [])
	check("trova_jump", not bad_jump.is_empty(), "Un salto verso un'etichetta non dichiarata deve essere segnalato")

	var bad_var: Array = call_if_exists(validator, "validate_lines", [[
		{"type": "line", "speaker": "Elena", "text": "Ho la spada!", "condition": {"variable": "ha_spada", "operator": "==", "value": true}}
	], "test.json"], [])
	check("trova_variabile", not bad_var.is_empty(), "Una condizione su una variabile mai impostata da un comando set deve generare un errore")

	var unreach: Array = call_if_exists(validator, "find_unreachable_labels", [[
		{"type": "jump", "target": "uscita"},
		{"type": "label", "id": "mai_usata"},
		{"type": "label", "id": "uscita"}
	]], [])
	check("trova_irraggiungibile", unreach.has("mai_usata"), "find_unreachable_labels deve identificare le etichette scavalcate e mai referenziate")

