class_name StoryValidator
extends EditorScript

const KNOWN_SPEAKERS: Array[String] = ["Elena", "Marco", "???", ""]


func _run() -> void:
	print("--- Inizio controllo storia ---")
	var chapters: Array[String] = [
		"res://story/intro.json",
		"res://story/branching_story.json",
		"res://story/network_story.json",
		"res://story/consequence_story.json"
	]
	var total_errors: int = 0
	for path in chapters:
		var errors := validate_chapter(path)
		if errors.is_empty():
			print("OK: %s" % path)
		else:
			for err in errors:
				printerr(err)
				total_errors += 1
	print("--- Controllo terminato: %d errori trovati ---" % total_errors)


func validate_chapter(file_path: String) -> Array[String]:
	if not FileAccess.file_exists(file_path):
		return ["%s: File non trovato." % file_path]

	var file := FileAccess.open(file_path, FileAccess.READ)
	if not file:
		return ["%s: Impossibile aprire il file." % file_path]

	var content: String = file.get_as_text()
	var json_data: Variant = JSON.parse_string(content)
	if not json_data is Dictionary:
		return ["%s: Il file non contiene un oggetto JSON valido." % file_path]

	var chapter: Dictionary = json_data
	var lines_variant: Variant = chapter.get("lines", [])
	if not lines_variant is Array:
		return ["%s: La chiave 'lines' non e' un array." % file_path]

	var lines: Array = lines_variant
	return validate_lines(lines, file_path)


func validate_lines(lines: Array, file_path: String = "storia.json") -> Array[String]:
	var errors: Array[String] = []
	var declared_labels: Dictionary = {}
	var assigned_variables: Array[String] = []

	# 1. Raccoglie etichette e variabili assegnate
	for i in range(lines.size()):
		var entry: Variant = lines[i]
		if not entry is Dictionary:
			continue
		var cmd: Dictionary = entry
		var cmd_type: String = String(cmd.get("type", ""))

		if cmd_type == "label":
			var label_name: String = String(cmd.get("id", cmd.get("name", "")))
			if label_name.is_empty():
				errors.append("%s [riga %d]: Etichetta senza nome specificato." % [file_path, i])
			elif declared_labels.has(label_name):
				errors.append("%s [riga %d]: Etichetta duplicata '%s'." % [file_path, i, label_name])
			else:
				declared_labels[label_name] = i

		if cmd_type == "set":
			var var_name: String = String(cmd.get("variable", ""))
			if not var_name.is_empty() and not assigned_variables.has(var_name):
				assigned_variables.append(var_name)

	# 2. Controlla personaggi, salti, scelte e condizioni
	for i in range(lines.size()):
		var entry: Variant = lines[i]
		if not entry is Dictionary:
			errors.append("%s [riga %d]: Elemento non valido nella lista comandi." % [file_path, i])
			continue

		var cmd: Dictionary = entry
		var speaker: String = String(cmd.get("speaker", ""))
		if not speaker.is_empty() and not KNOWN_SPEAKERS.has(speaker):
			errors.append("%s [riga %d]: Personaggio sconosciuto '%s'." % [file_path, i, speaker])

		var cmd_type: String = String(cmd.get("type", ""))
		if cmd_type == "jump":
			var target: String = String(cmd.get("target", ""))
			if target.is_empty() or not declared_labels.has(target):
				errors.append("%s [riga %d]: Salto verso etichetta inesistente '%s'." % [file_path, i, target])

		if cmd_type == "choice":
			var options: Variant = cmd.get("options", [])
			if options is Array:
				for opt in options:
					if opt is Dictionary:
						var opt_target: String = String(opt.get("target", ""))
						if opt_target.is_empty() or not declared_labels.has(opt_target):
							errors.append("%s [riga %d]: Scelta con salto verso etichetta inesistente '%s'." % [file_path, i, opt_target])
						if opt.has("condition"):
							var cond: Variant = opt.get("condition")
							if cond is Dictionary:
								var cond_var: String = String(cond.get("variable", ""))
								if not cond_var.is_empty() and not assigned_variables.has(cond_var):
									errors.append("%s [riga %d]: Condizione su variabile mai impostata '%s'." % [file_path, i, cond_var])

		if cmd.has("condition"):
			var cond: Variant = cmd.get("condition")
			if cond is Dictionary:
				var cond_var: String = String(cond.get("variable", ""))
				if not cond_var.is_empty() and not assigned_variables.has(cond_var):
					errors.append("%s [riga %d]: Condizione su variabile mai impostata '%s'." % [file_path, i, cond_var])

	# 3. Controllo etichette non raggiungibili
	var unreachable := find_unreachable_labels(lines)
	for unreach in unreachable:
		var line_idx: int = declared_labels.get(unreach, -1)
		errors.append("%s [riga %d]: Etichetta mai raggiungibile '%s'." % [file_path, line_idx, unreach])

	return errors


func find_unreachable_labels(commands: Array) -> Array[String]:
	var all_labels: Dictionary = {}
	for i in range(commands.size()):
		var cmd: Variant = commands[i]
		if cmd is Dictionary and cmd.get("type", "") == "label":
			var lid: String = String(cmd.get("id", cmd.get("name", "")))
			if not lid.is_empty():
				all_labels[lid] = i

	if all_labels.is_empty():
		return []

	var visited_indices: Array[int] = []
	var queue: Array[int] = [0]

	while not queue.is_empty():
		var idx: int = queue.pop_front()
		if idx < 0 or idx >= commands.size():
			continue
		if visited_indices.has(idx):
			continue
		visited_indices.append(idx)

		var cmd: Variant = commands[idx]
		if not cmd is Dictionary:
			queue.append(idx + 1)
			continue

		var cmd_type: String = String(cmd.get("type", ""))
		match cmd_type:
			"jump":
				var target: String = String(cmd.get("target", ""))
				if all_labels.has(target):
					queue.append(all_labels[target])
			"choice":
				var options: Variant = cmd.get("options", [])
				if options is Array:
					for opt in options:
						if opt is Dictionary:
							var target: String = String(opt.get("target", ""))
							if all_labels.has(target):
								queue.append(all_labels[target])
			_:
				queue.append(idx + 1)

	var unreachable: Array[String] = []
	for label_name in all_labels:
		var label_idx: int = all_labels[label_name]
		if not visited_indices.has(label_idx):
			unreachable.append(label_name)

	return unreachable

